window.OmniFeature=a=>{const graphs=new Map();let button=null;function apply(g){if(!g.enabled)return;const s=a.settings.all(),at=g.context.currentTime;g.gain.gain.setTargetAtTime(Math.max(0,Math.min(2,Number(s.volume)/100||0)),at,.02);for(const [node,key]of [[g.low,'bass'],[g.mid,'mid'],[g.high,'treble']])node.gain.setTargetAtTime(Math.max(-12,Math.min(12,Number(s[key])||0)),at,.02);g.compressor.threshold.value=s.night?-24:0;g.compressor.ratio.value=s.night?4:1;g.compressor.knee.value=s.night?20:0;g.compressor.attack.value=.01;g.compressor.release.value=.25;if(s.remember)a.storage.set('volume:'+location.hostname,Math.max(0,Math.min(200,Number(s.volume)||0))).catch(()=>{})}async function attach(){const C=window.AudioContext||window.webkitAudioContext;if(!C){a.toast('Web Audio is unavailable.').catch(()=>{});return}const media=[...document.querySelectorAll('audio,video')].find(e=>{try{return !e.srcObject&&new URL(e.currentSrc||e.src,location.href).origin===location.origin&&!!(e.currentSrc||e.src)}catch(_){return false}});if(!media){a.toast('Choose same-origin media first; cross-origin media is unchanged.').catch(()=>{});return}try{let g=graphs.get(media);if(!g){if(graphs.size>=4){a.toast('Audio tools limit reached. Reload to release old graphs.').catch(()=>{});return}const context=new C(),source=context.createMediaElementSource(media),gain=context.createGain(),low=context.createBiquadFilter(),mid=context.createBiquadFilter(),high=context.createBiquadFilter(),compressor=context.createDynamicsCompressor();low.type='lowshelf';low.frequency.value=200;mid.type='peaking';mid.frequency.value=1000;mid.Q.value=.7;high.type='highshelf';high.frequency.value=5000;source.connect(context.destination);g={context,source,gain,low,mid,high,compressor,enabled:false};gain.connect(low);low.connect(mid);mid.connect(high);high.connect(compressor);compressor.connect(context.destination);graphs.set(media,g)}await g.context.resume();if(!a.active)return;g.source.disconnect();g.source.connect(g.gain);g.enabled=true;apply(g);a.toast('Audio tools attached. Playback remains under your control.').catch(()=>{})}catch(_){a.toast('This media cannot use Audio tools. Reload if its audio changed.').catch(()=>{})}}function bypass(){for(const g of graphs.values()){g.enabled=false;g.source.disconnect();g.source.connect(g.context.destination)}}return{enable(){if(a.settings.get('remember')){const saved=a.storage.get('volume:'+location.hostname);if(Number.isFinite(saved)&&saved>=0&&saved<=200)a.settings.set('volume',saved).catch(()=>{})}button=document.createElement('button');button.className='ob-audio-tools';button.textContent='Audio tools · Apply to media';button.onclick=e=>{if(e.isTrusted)attach()};document.documentElement.append(button)},update(){if(a.active)for(const g of graphs.values())apply(g)},disable(){button?.remove();button=null;bypass()}}};